import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

const UPLOADS = [
  { kind: "w9", file: "w9.pdf" },
  { kind: "insurance_certificate", file: "insurance_certificate.pdf" },
  { kind: "contract", file: "contract.pdf" },
] as const;

// Each vendor's documents are chosen so extraction yields the scenario's lowest
// field confidence. Samples are assumed to produce these values.
const LOW_CONFIDENCE_SAMPLES = ["w9.pdf", "insurance_certificate.pdf", "contract.pdf"];
const HIGH_CONFIDENCE_SAMPLES = ["w9.pdf", "insurance_certificate.pdf", "contract.pdf"];

type Vendor = { id: string; name: string };
type Doc = { id: string; status: string };
type QueueItem = { vendor_id: string; vendor_name: string; lowest_confidence: number };

test.describe("review queue ordering", () => {
  test(
    "The review queue shows lowest confidence first",
    { tag: "@REV-03" },
    async ({ apiAs }) => {
      // Arrange: a member creates two vendors and submits each once extracted.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");

      const createAndSubmit = async (label: string, files: string[]): Promise<Vendor> => {
        const created = await member.post("/api/vendors", {
          data: {
            name: uniqueName(label),
            category: "software",
            contact_email: `${label.replace(/\W+/g, "").toLowerCase()}@vendor.test`,
          },
        });
        expect(created.status()).toBe(201);
        const vendor = (await created.json()) as Vendor;

        for (let i = 0; i < UPLOADS.length; i++) {
          const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
            multipart: {
              kind: UPLOADS[i].kind,
              file: {
                name: files[i],
                mimeType: "application/octet-stream",
                buffer: readFileSync(sample(files[i])),
              },
            },
          });
          expect(upload.status()).toBe(201);
          const doc = (await upload.json()) as Doc;

          await expect
            .poll(
              async () => {
                const res = await member.get(`/api/documents/${doc.id}`);
                return ((await res.json()) as Doc).status;
              },
              { timeout: 60_000 },
            )
            .toBe("extracted");
        }

        const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
        expect(submitted.status()).toBe(200);
        expect((await submitted.json()).status).toBe("in_review");
        return vendor;
      };

      const low = await createAndSubmit("Review Low", LOW_CONFIDENCE_SAMPLES);
      const high = await createAndSubmit("Review High", HIGH_CONFIDENCE_SAMPLES);

      // Act
      const response = await reviewer.get("/api/review-queue");

      // Assert
      expect(response.status()).toBe(200);
      const queue = (await response.json()) as QueueItem[];

      // The queue as a whole is ordered by lowest confidence, ascending.
      for (let i = 1; i < queue.length; i++) {
        expect(queue[i - 1].lowest_confidence).toBeLessThanOrEqual(queue[i].lowest_confidence);
      }

      const lowItem = queue.find((item) => item.vendor_id === low.id);
      const highItem = queue.find((item) => item.vendor_id === high.id);
      expect(lowItem, "low-confidence vendor is in the queue").toBeDefined();
      expect(highItem, "high-confidence vendor is in the queue").toBeDefined();

      expect(lowItem!.lowest_confidence).toBeCloseTo(0.4, 2);
      expect(highItem!.lowest_confidence).toBeCloseTo(0.95, 2);
      expect(queue.indexOf(lowItem!)).toBeLessThan(queue.indexOf(highItem!));
    },
  );
});
